import { describe, expect, it } from "vitest";

import { assertSafeStorageKey, StorageKeyError } from "@/lib/storage/types";

/**
 * Storage keys are generated by the application, but validation still runs on
 * every read and write so a corrupted database row cannot escape the storage
 * root or bucket prefix.
 */
describe("assertSafeStorageKey", () => {
  it("accepts nested generated keys", () => {
    expect(assertSafeStorageKey("media/2026/11/2b1f0f4c-0000-4000-8000-000000000000.png")).toBe(
      "media/2026/11/2b1f0f4c-0000-4000-8000-000000000000.png",
    );
  });

  it.each([
    ["parent traversal", "media/../../etc/passwd"],
    ["absolute path", "/etc/passwd"],
    ["windows separator", "media\\file.png"],
    ["empty segment", "media//file.png"],
    ["dot segment", "media/./file.png"],
    ["only dot", "."],
    ["empty key", ""],
    ["control character", "media/\u0000file.png"],
    ["url-ish characters", "media/file%2e%2e.png"],
    ["space", "media/my file.png"],
    ["double dot inside a segment", "media/file..png"],
  ])("rejects %s", (_label, key) => {
    expect(() => assertSafeStorageKey(key)).toThrowError(StorageKeyError);
  });

  it("rejects keys above 300 characters", () => {
    expect(() => assertSafeStorageKey("a".repeat(301))).toThrowError(StorageKeyError);
  });

  it("allows repeated dashes and dots in generated names", () => {
    expect(assertSafeStorageKey("media/2026/11/a-b-c.png")).toBe("media/2026/11/a-b-c.png");
  });
});